package dev.odin.controls;
public final class ZoneFrameTest {
 static void check(boolean v){if(!v)throw new AssertionError();}
 static void rejects(String s,ZoneFrame before){try{ZoneFrame.parse(s,before);throw new AssertionError(s);}catch(IllegalArgumentException expected){}}
 public static void main(String[] args){ZoneFrame base=new ZoneFrame(new String[]{"ABCDEF","ABCDEF","ABCDEF","ABCDEF"},new int[]{50,50,50,50},"0101");ZoneFrame custom=ZoneFrame.parse("light-zones ff0000 0000ff 00ff00 ff8000 100 50 25 75 keep",base);check(custom.mask.equals("1101"));check(custom.colors[0].equals("FF0000")&&custom.levels[2]==25);check(base.colors[0].equals("ABCDEF")&&base.mask.equals("0101"));check(ZoneFrame.parse(custom.request(),base).request().equals(custom.request()));ZoneFrame off=ZoneFrame.parse("light-off",custom);check(off.mask.equals("0000")&&off.colors[0].equals("FF0000")&&off.levels[3]==75);ZoneFrame one=ZoneFrame.parse("light-one 2 123456 10 system",off);check(one.mask.equals("0010")&&one.levels[2]==10&&one.colors[2].equals("123456")&&one.colors[3].equals("FF8000")&&one.levels[3]==75);ZoneFrame groups=ZoneFrame.parse("light-groups FF0000 0000FF 00FF00 FF8000 100 50 25 75 on off",one);check(groups.mask.equals("0011"));check(ZoneFrame.parse(groups.request(),base).request().equals(groups.request()));for(String bad:new String[]{"light-one 4 FFFFFF 50","light-one 0 FF0000 101","light-one 0 FF0000 -1","light-one 0 FF0000 50 surprise","light-off extra","light-zones FF0000 0000FF 00FF00 FF8000 100 50 25 75 keep 1112","light-groups FF0000 0000FF 00FF00 FF8000 100 50 25 75 on maybe","light-zones FF0000 0000FF 00FF00 FF8000 100 50 25 75 bad","light-zones FF000G 0000FF 00FF00 FF8000 100 50 25 75 on"})rejects(bad,base);System.out.println("PASS Odin2 frame roundtrip, independent colors/brightness, side retention, group masks, all-off retention, single-zone reenable and invalid input rejection");}
}
